export const freshReading=()=>({font:'normal',mode:'calm',pins:[],favorites:[],read:[]});
export function fingerprint(value){const text=JSON.stringify(value);let a=2166136261,b=2246822519;for(let i=0;i<text.length;i++){a=Math.imul(a^text.charCodeAt(i),16777619);b=Math.imul(b^text.charCodeAt(i),3266489917);}return (a>>>0).toString(36)+'-'+(b>>>0).toString(36)+'-'+text.length.toString(36);}
export function entryKey(entry){return fingerprint([entry.id,entry.cast,entry.title,entry.text,entry.options,entry.choice,entry.result]);}
export function sceneKey(event){return fingerprint([event.id,event.npc,event.other,event.title,event.subtitle,event.text,event.choices]);}
export function rememberReading(reading,event,choice){const key=sceneKey(event);reading.read=reading.read.filter(x=>x.key!==key);reading.read.push({key,choice});reading.read=reading.read.slice(-600);}
export function previousChoice(reading,event){if(!event||!(/^(arc:|daily-|circle-|encore-|after-)/.test(event.id)||event.id&&['quiet','newbie','stars','dance','distance','mesh','orange','voice','rumor','budget','morning','party','feedback','alone','hostlesson'].includes(event.id)))return null;const previous=reading.read.find(x=>x.key===sceneKey(event));return previous&&event.choices[previous.choice]&&!event.choices[previous.choice].unavailable?previous.choice:null;}
export const MESSAGE_CATEGORIES={all:'全部近况',change:'计划变化',life:'个人计划',relationship:'关系与群像',world:'世界后续',theme:'旅程主题',finale:'阶段小结'};
export function messageCategory(q){return q.id==='life-change'?'change':q.id.startsWith('life-')?'life':q.id.startsWith('after-')?'world':(q.id.startsWith('encore-')||q.id.startsWith('turn-'))?'theme':q.id.startsWith('finale-')?'finale':'relationship';}
export function messageKey(q){return fingerprint([q.id,q.npc,q.other,q.index,q.booking,q.change]);}
export function toggleReading(list,key,max=128){const index=list.indexOf(key);if(index>=0)list.splice(index,1);else {list.push(key);if(list.length>max)list.shift();}}
export function searchBook(book,{person='all',query='',favorites=false,keys=[]}={}){const words=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);return book.filter(x=>(person==='all'||x.cast.includes(person))&&(!favorites||keys.includes(entryKey(x)))&&words.every(word=>[x.title,x.subtitle,x.text,x.result,...x.options].join('\n').toLocaleLowerCase().includes(word)));}
export function validReader(x){const keys=(a,n)=>Array.isArray(a)&&a.length<=n&&new Set(a).size===a.length&&a.every(s=>typeof s==='string'&&/^[a-z0-9]+-[a-z0-9]+-[a-z0-9]+$/.test(s)&&s.length<=50);return !!x&&['calm','full'].includes(x.mode)&&['small','normal','large'].includes(x.font)&&keys(x.pins,128)&&keys(x.favorites,300)&&Array.isArray(x.read)&&x.read.length<=600&&new Set(x.read.map(r=>r?.key)).size===x.read.length&&x.read.every(r=>r&&keys([r.key],1)&&Number.isInteger(r.choice)&&r.choice>=0&&r.choice<=5);}
